            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x1EACDE20CD4BF78BULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0x2B1AB56C304AD138ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
