            //
            aWandererI = aWandererI + (((RotL64(aCross, 12U) + aOrbiterF) + RotL64(aOrbiterJ, 51U)) + aTwistWandererUpdateSaltE[((aIndex + 8U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 19U) + RotL64(aOrbiterG, 42U)) + aOrbiterI);
            aWandererD = aWandererD + (((RotL64(aScatter, 35U) + aOrbiterJ) + RotL64(aOrbiterC, 29U)) + RotL64(aCarry, 51U));
            aWandererB = aWandererB ^ ((RotL64(aIngress, 41U) + aOrbiterF) + RotL64(aOrbiterI, 19U));
