            //
            aOrbiterK = ((aWandererG + RotL64(aIngress, 5U)) + 0x0C9484B024724C86ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aScatter, 19U)) + 0x0A1CB1A123B921A7ULL;
            aOrbiterE = (aWandererE + RotL64(aPrevious, 29U)) + 0x2583C399BCF6031AULL;
            aOrbiterD = (aWandererI + RotL64(aCross, 57U)) + 0xEA9CADA1F9D6BF68ULL;
            aOrbiterI = (((aWandererK + RotL64(aIngress, 41U)) + RotL64(aCarry, 23U)) + 0x3167DF3CED0DD0CAULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterF = ((aWandererH + RotL64(aCross, 12U)) + RotL64(aCarry, 57U)) + 0x21F71AABF23874D1ULL;
