            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xAB69B3D76923ABB5ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x35ED1042819A408AULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x265C3C0AFD40DC45ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x2D544606A50E8975ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0xD2838FBC3C7DF1D0ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 27U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x10F84ADB0384A29BULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x3A855C5CE9EF8646ULL;
