            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xB839E16C123D3692ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0xD568D5914965D32FULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 10U)) & S_SALT1];
