            aOrbiterE = (((aWandererB + RotL64(aCross, 29U)) + RotL64(aCarry, 11U)) + 0xB7207D527978F686ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterJ = ((aWandererC + RotL64(aScatter, 19U)) + RotL64(aCarry, 27U)) + 0x93D3B65B56D8A2E9ULL;
