            aOrbiterC = ((aWandererF + RotL64(aIngress, 19U)) + 0x7DEDA73977A6570DULL) + aTwistOrbiterAssignSaltA[((aIndex + 4U)) & S_SALT1];
            aOrbiterH = ((aWandererG + RotL64(aPrevious, 47U)) + RotL64(aCarry, 21U)) + 0xC8A356ED60517CBDULL;
