            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x2932FA56F9D7BE23ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 8U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x6B5E8C82C23CD63AULL;
