            aOrbiterH = RotL64((aOrbiterH * 0x3BC79862F9D3D6C5ULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0xC067D0D67F115533ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0xC3B354501CA9CB6AULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 24U)) & S_SALT1];
