            //
            aWandererE = aWandererE ^ (((RotL64(aCross, 5U) + RotL64(aOrbiterI, 53U)) + aOrbiterH) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 21U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aIngress, 43U) + aOrbiterA) + RotL64(aOrbiterF, 11U)) + RotL64(aCarry, 3U));
