            aCross ^= (RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 9770U)) & S_BLOCK1], 3U) ^ RotL64(aSoilLaneA[((aIndex + 8675U)) & S_BLOCK1], 47U));
