            aOrbiterE = ((aWandererI + RotL64(aScatter, 51U)) + RotL64(aCarry, 29U)) + 0x9F9E66C0D35E93D6ULL;
            aOrbiterB = ((aWandererD + RotL64(aCross, 19U)) + 0xF5C2AE48095B6CE3ULL) + aTwistOrbiterAssignSaltA[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = (aWandererJ + RotL64(aIngress, 24U)) + 0x7D8DD83DEB6397A7ULL;
