            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 1740U)) & W_KEY1], 41U) ^ RotL64(aPoisonLaneA[((aIndex + 2727U)) & S_BLOCK1], 56U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 54U) + RotL64(aCross, 19U)) ^ (RotL64(aIngress, 3U) + RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = ((aWandererG + RotL64(aIngress, 41U)) + RotL64(aCarry, 41U)) + 0x8B5A442258F92DAEULL;
            aOrbiterC = ((aWandererH + RotL64(aCross, 30U)) + 0xE388917DEFBFABCDULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterF = (aWandererA + RotL64(aScatter, 5U)) + 0x94EE3C9905441E10ULL;
            aOrbiterG = (aWandererI + RotL64(aPrevious, 43U)) + 0x84DEA290B4B9F78FULL;
            aOrbiterD = ((aWandererJ + RotL64(aScatter, 11U)) + RotL64(aCarry, 53U)) + 0x3845AA4F828CCBC7ULL;
            aOrbiterJ = (aWandererD + RotL64(aCross, 27U)) + 0x7EA91BF2D4FA43A7ULL;
            aOrbiterK = (aWandererC + RotL64(aIngress, 37U)) + 0x8242C6BC4C37149DULL;
            aOrbiterB = (((aWandererK + RotL64(aPrevious, 18U)) + RotL64(aCarry, 29U)) + 0x45704289D7E9CE6EULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aCross, 21U)) + 0x5A845FC3670A8834ULL;
            aOrbiterA = (aWandererF + RotL64(aIngress, 23U)) + 0xBB42C047A8DBABBFULL;
            aOrbiterE = (aWandererE + RotL64(aPrevious, 47U)) + 0xC0E7791B89E3A404ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xD8448D935DC4D206ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x3FBE71577AE663A5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC96E8C942F874EA5ULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xE0ED647D919F1531ULL;
