            aOrbiterC = RotL64((aOrbiterC * 0x4CCCBABAC77A82EFULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x3DED1333E7913F19ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xC081BCBB51315C32ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xE1823BEB166908E3ULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0xF057F1EE069F6905ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x3EA3124BB674691DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x98719529CBE3A849ULL), 27U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0xEA21AE7142C096CBULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xBBC10A897416A3DEULL;
            aOrbiterA = RotL64((aOrbiterA * 0x2447793E0B76E067ULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xD6A1755B5957D237ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x2C817AF5728595B9ULL;
