            aWandererG = aWandererG ^ (((RotL64(aScatter, 47U) + aOrbiterJ) + RotL64(aOrbiterF, 56U)) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 21U)) & S_SALT1]);
