            aWandererA = aWandererA ^ (((RotL64(aPrevious, 57U) + aOrbiterK) + RotL64(aOrbiterG, 47U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 9U)) & S_SALT1]);
