            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x4B7CF2341DAAF9F1ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x1F79D998096F5E63ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5E0701FDD5579191ULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xC5739572EFCDCCB5ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x22101120B84A7A54ULL;
