            aWandererJ = aWandererJ ^ (((RotL64(aCross, 13U) + RotL64(aOrbiterA, 58U)) + aOrbiterH) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1]);
