            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x8D8C050EA0A60211ULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x58A372DAF2D94FAEULL;
