            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0x6A4416EE14A3DDFDULL) + aKeySpawnOrbiterUpdateSaltE[((aIndex + 6U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xA04DDF3E4CA73F43ULL;
