            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x3560C7C4D835477CULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0x4B8B838BBF31D5ADULL) ^ aKeySpawnOrbiterUpdateSaltC[((aIndex + 4U)) & S_SALT1];
