            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x5832AEB3B145CAA5ULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xD1AF2431550775ADULL;
            aOrbiterG = RotL64((aOrbiterG * 0x25CFD4AA5D423C8DULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x8C4A84D177782785ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x77E3C62650593390ULL;
